/**
 * What the server says about SRS v2 for this account (GET /me/srs), kept in
 * meta `srs` so every screen and every grade reads it locally on the first
 * frame. It changes only when an operator changes the flag, so it is read
 * again at most every `SRS_REFRESH_MS` with the sync, and at once when the
 * schedule page opens.
 */
import { isApiError } from '@/api/errors.js';
import { me } from '@/api/endpoints.js';
import { db, getMeta, setMeta, type LexpadDb, type MetaShape } from '@/db/schema.js';

/**
 * How stale the copy may get before a sync reads it again. A client-side
 * freshness choice, not a server value: the flag is changed by hand, rarely,
 * and one extra request per sync for it would be waste.
 */
export const SRS_REFRESH_MS = 10 * 60_000;

/**
 * Reads GET /me/srs into meta, unless the copy is fresh. A server without
 * the endpoint answers 404, which is stored as "none" so it is not asked on
 * every sync either. Offline and server errors keep the copy as it was.
 */
export async function refreshSrs(
  options: { force?: boolean; now?: Date } = {},
  database: LexpadDb = db,
): Promise<MetaShape['srs']> {
  const now = options.now ?? new Date();
  const current = await getMeta('srs', database);
  if (options.force !== true && current !== null && now.getTime() - Date.parse(current.at) < SRS_REFRESH_MS) {
    return current;
  }
  let next: MetaShape['srs'];
  try {
    next = { at: now.toISOString(), state: await me.srs() };
  } catch (error) {
    if (!isApiError(error, 'notFound')) return current;
    next = { at: now.toISOString(), state: null };
  }
  await setMeta('srs', next, database);
  return next;
}
